import{_ as a,o as t,c as i,ag as r}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"声明审计：GPT-6 Astra「攻克哥德巴赫」是标题压缩","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/liouville-goldbach-astra-claim.md","filePath":"topics/ai-system-architecture/liouville-goldbach-astra-claim.md"}'),o={name:"topics/ai-system-architecture/liouville-goldbach-astra-claim.md"};function l(s,e,n,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[r(`<h1 id="声明审计-gpt-6-astra「攻克哥德巴赫」是标题压缩" tabindex="-1">声明审计：GPT-6 Astra「攻克哥德巴赫」是标题压缩 <a class="header-anchor" href="#声明审计-gpt-6-astra「攻克哥德巴赫」是标题压缩" aria-label="Permalink to &quot;声明审计：GPT-6 Astra「攻克哥德巴赫」是标题压缩&quot;">​</a></h1><blockquote><p>入库身份：<strong>声明审计</strong>，不是「哥德巴赫已证」事实条。 触发转述：<code>GPT-6 Astra 攻克哥德巴赫猜想：该数学突破已通过 Lean 4 形式化验证，被视为大模型科研能力里程碑。</code> 二次传播：新智元 / 36氪 2026-09-21 10:29（英译页 <code>eu.36kr.com/en/p/3992525310802946</code>） 一手仓库：<a href="https://github.com/CaptainSude/Liouville-Goldbach" target="_blank" rel="noreferrer"><code>CaptainSude/Liouville-Goldbach</code></a>（创建 2026-09-16，无 license，本稿核验时 8★ / 0 fork，最后 push 仍是创建当日） 核验日：2026-09-21 关键词：刘维尔、哥德巴赫、Lean、Astra、Overclaim、形式化、sorry、MathOverflow、Mangerel</p></blockquote><hr><h2 id="一句话" tabindex="-1">一句话 <a class="header-anchor" href="#一句话" aria-label="Permalink to &quot;一句话&quot;">​</a></h2><p>仓库里能读到的定理是：<strong>每个偶数 N&gt;2 可写成两个刘维尔值 λ=-1 的正整数之和</strong>。这比「两个素数之和」弱一截；经典哥德巴赫在 Wikipedia 信息框仍标 <code>Open problem Yes</code>。Lean 核验的是这句弱定理，不是 1+1。</p><h2 id="原文-vs-转述" tabindex="-1">原文 vs 转述 <a class="header-anchor" href="#原文-vs-转述" aria-label="Permalink to &quot;原文 vs 转述&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层级</th><th>说了什么</th><th>核验</th></tr></thead><tbody><tr><td>用户/标题压缩</td><td>GPT-6 Astra 攻克哥德巴赫；Lean 4 已形式化；大模型科研里程碑</td><td>❌ 定理对象被换掉；里程碑是媒体评价，不是仓库自称</td></tr><tr><td>新智元正文中段</td><td>Captain Sude 宣布 Astra 证明了<strong>关于刘维尔函数的类哥德巴赫命题</strong>；无条件、全体偶数</td><td>⚠️ 命题方向对，但把发现与形式化都记在 Astra 账上——一手 PDF/README <strong>零次</strong>出现 Astra / GPT / OpenAI</td></tr><tr><td>新智元正文后段</td><td>「必须严谨地说：还没有」彻底解决经典猜想；中间仍隔「奇数个质因数的合数 → 素数」</td><td>✅ 与仓库、与 Wikipedia 一致；标题没把这段带上</td></tr><tr><td>仓库 README / <code>verification.json</code></td><td><code>LiouvilleGoldbach.liouville_goldbach</code>：Even N ∧ 2&lt;N → ∃ a,b&gt;0，a+b=N 且 <code>ArithmeticFunction.liouville</code> 两边 = -1</td><td>✅ 2026-09-16 04:43 UTC 自报 build/axiom/route 三项 passed</td></tr><tr><td>Wikipedia</td><td>Goldbach&#39;s conjecture，信息框 <code>Open problem Yes</code></td><td>✅ 2026-09-21 抓取</td></tr></tbody></table><p>λ(n)=(-1)^{Ω(n)}。素数的 λ 一定是 -1，但反过来不成立：λ(8)=λ(12)=-1，所以 20=8+12 对弱定理合法，对经典哥德巴赫不算。弱定理是经典猜想的<strong>推论方向</strong>（经典真 ⇒ 弱定理真），不是等价物。</p><h2 id="定理原文-仓库-不是新闻" tabindex="-1">定理原文（仓库，不是新闻） <a class="header-anchor" href="#定理原文-仓库-不是新闻" aria-label="Permalink to &quot;定理原文（仓库，不是新闻）&quot;">​</a></h2><div class="language-lean vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lean</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">theorem</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> liouville_goldbach</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (N : ℕ) (hEven : Even N) (hN : </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt; N) :</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ∃ a b : ℕ, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt; a ∧ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &lt; b ∧ a + b = N ∧</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ArithmeticFunction.liouville a = -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ∧</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ArithmeticFunction.liouville b = -</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span></code></pre></div><p>论文标题是 <em>A Goldbach theorem for the Liouville function</em>，<code>pdfauthor={}</code> 为空。问题来源：MathOverflow <a href="https://mathoverflow.net/questions/307479/goldbachs-conjecture-for-the-liouville-function" target="_blank" rel="noreferrer">307479</a>（2018-08，用户 Pablo；页面 2026-09-21 仍在）。Mangerel 把同一问题记到 Shusterman 名下。</p><h2 id="lean-核验能撑住什么、撑不住什么" tabindex="-1">Lean 核验能撑住什么、撑不住什么 <a class="header-anchor" href="#lean-核验能撑住什么、撑不住什么" aria-label="Permalink to &quot;Lean 核验能撑住什么、撑不住什么&quot;">​</a></h2><p>上游 <code>lean/verification.json</code>（自报，本稿<strong>未</strong>本地 <code>lake build</code>）：</p><ul><li>Lean <code>v4.34.0-rc2</code>，mathlib <code>de2ef68216c6074f338c8e61890ee0a379ddfb9b</code></li><li>终定理公理只剩 <code>propext</code> / <code>Classical.choice</code> / <code>Quot.sound</code>（Lean 常规底，不是刘维尔–哥德巴赫假设）</li><li><code>sorry_or_custom_axioms: false</code>；源码自报无 <code>sorry</code> / <code>admit</code> / <code>native_decide</code> / <code>unsafe</code></li><li>仓库写明：Mangerel、GRH、类数分类、有限数值核验<strong>都不是</strong>该发展的假设</li></ul><p>独立回放：<a href="https://github.com/sunnyspot114514/Liouville-Goldbach-audit" target="_blank" rel="noreferrer"><code>sunnyspot114514/Liouville-Goldbach-audit</code></a>（2026-09-17，0★）冻结 <code>v1.0.0</code> / <code>da3c528…</code>，自报 <code>lake build</code> PASS、陈述与论文一致、偶数 N∈{4,…,500} 共 249 次冒烟 0 失败。它自己写了分离规则：<strong>不是期刊背书，也不替代同行评审</strong>。249 次冒烟是抽样，不是证明。</p><p>「通过 Lean = 逻辑上绝对正确」是媒体句。Lean 只保证：<strong>被写下的那条陈述</strong>相对内核与 mathlib 无洞。陈述若弱，证成的也弱。</p><h2 id="和既有解析结果的关系-36氪把两篇-mangerel-拧在一起了" tabindex="-1">和既有解析结果的关系（36氪把两篇 Mangerel 拧在一起了） <a class="header-anchor" href="#和既有解析结果的关系-36氪把两篇-mangerel-拧在一起了" aria-label="Permalink to &quot;和既有解析结果的关系（36氪把两篇 Mangerel 拧在一起了）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文献</th><th>实际题目（arXiv API 2026-09-21）</th><th>角色</th></tr></thead><tbody><tr><td><a href="https://arxiv.org/abs/2404.12117" target="_blank" rel="noreferrer">arXiv:2404.12117</a></td><td><em>On a Goldbach-type problem for the Liouville function</em></td><td>36氪「突破黎曼阴影」主链误挂到这篇</td></tr><tr><td><a href="https://arxiv.org/abs/2412.17199" target="_blank" rel="noreferrer">arXiv:2412.17199</a></td><td><em>On Shusterman&#39;s Goldbach-type problem for sign patterns of the Liouville function</em></td><td>仓库论文 bibliography 引用的 Shusterman 型结果；媒体说的 GRH + 充分大，应对这篇</td></tr><tr><td><a href="https://arxiv.org/abs/2608.13266" target="_blank" rel="noreferrer">arXiv:2608.13266</a></td><td><em>On a conjecture of Corradi and Katai</em></td><td>仓库论文另引，不是经典哥德巴赫</td></tr></tbody></table><p>仓库声称相对 Mangerel 的增量是：去掉 GRH、去掉「充分大」、覆盖全体偶数 N&gt;2。这是<strong>作者主张</strong>；本稿只核对「主张写在哪」，未做数学审稿。</p><p>兄弟仓库 <code>CaptainSude/Liouville-Goldbach-Multiples-of-Four</code> 是「4 的倍数」先行稿，被主论文引用，不是另一套经典哥德巴赫证明。</p><h2 id="astra-归因-二手有、一手无" tabindex="-1">Astra 归因：二手有、一手无 <a class="header-anchor" href="#astra-归因-二手有、一手无" aria-label="Permalink to &quot;Astra 归因：二手有、一手无&quot;">​</a></h2><ul><li>仓库 README、<code>lean/README.md</code>、论文 TeX：<strong>Astra / GPT / OpenAI 出现次数 = 0</strong></li><li>发现叙事（「第一天 4 的倍数、第二天全体偶数」「两页 PDF」「优雅而非算力」）只出现在新智元/Captain Sude 的对外转述</li><li>因此可写的最强句是：<strong>存在一份 2026-09-16 的 Lean 工程，作者账号 CaptainSude，声称无条件证明刘维尔–哥德巴赫；媒体把它记在 GPT-6 Astra 名下。</strong> 不能写成「OpenAI 官方里程碑」</li></ul><p>勿与下列仓库合并：</p><ul><li><a href="https://github.com/openai/ten-proofs" target="_blank" rel="noreferrer"><code>openai/ten-proofs</code></a>：另一包形式化结果，<strong>不是</strong>哥德巴赫</li><li><a href="https://github.com/anthropics/fermats-last-theorem" target="_blank" rel="noreferrer"><code>anthropics/fermats-last-theorem</code></a>：Claude 形式化<strong>已有</strong>怀尔斯证明，见 <a href="/zhishiku-reading/topics/ai-system-architecture/weekly-412-analysis.html">weekly-412</a>——那是验证，不是发现</li><li><code>gersh/ternary-goldbach-lean</code>：三素数（弱）哥德巴赫，奇数 ≥7 = 三素数之和；信任边界里有大量 <code>native_decide</code>，和本仓库「无 native_decide」不是同一套账</li></ul><h2 id="和本库其它条的对齐" tabindex="-1">和本库其它条的对齐 <a class="header-anchor" href="#和本库其它条的对齐" aria-label="Permalink to &quot;和本库其它条的对齐&quot;">​</a></h2><ul><li><a href="/zhishiku-reading/topics/ai-system-architecture/science-daily-2026-09-21.html">OverclaimBench</a>（arXiv:2609.20812）：最终回复与上下文矛盾。本条同构——标题「攻克哥德巴赫」，上下文（仓库定理、新闻后段、Wikipedia）写的是弱形式未证经典。</li><li><a href="/zhishiku-reading/topics/ai-system-architecture/weekly-412-analysis.html">周刊 #412</a>：Claude×FLT 是把 129 页人类证明译成 Lean，Buzzard 的分寸是「除数学公理外无额外假设」。本条若属实，增量在<strong>弱命题的初等证明 + 形式化</strong>，仍不是经典 1+1。</li><li><a href="/zhishiku-reading/topics/philosophy/mathematics.html">数学思维</a>：证明思维=不轻信断言。开放问题被改名包装后，先对陈述，再对故事。</li></ul><h2 id="入库规则-以后引用本条时" tabindex="-1">入库规则（以后引用本条时） <a class="header-anchor" href="#入库规则-以后引用本条时" aria-label="Permalink to &quot;入库规则（以后引用本条时）&quot;">​</a></h2><ol><li>禁止写成「哥德巴赫猜想已被证明」。</li><li>引用定理必须带 λ=-1，或写全称「刘维尔–哥德巴赫」。</li><li>Astra 只标「媒体/作者对外归因」，不标「官方论文作者」。</li><li>Lean 只标「上游自报 + 第三方回放仓库自报」，不冒充本稿本地复编译。</li><li>经典哥德巴赫状态以百科/专业综述为准；2026-09-21 仍为开放。</li></ol>`,28)])])}const g=a(o,[["render",l]]);export{u as __pageData,g as default};
